[{"order":1,"type":"heading","text":"Raycasting, Overlap Queries, and Character Controllers in Unity"},{"order":2,"type":"paragraph","text":"Physics queries and character movement are foundational pillars of game development in Unity. Whether you are detecting line-of-sight, checking for interactive objects in an area, or moving a player smoothly across complex geometry, mastering Physics.Raycast, Physics.OverlapSphere, and the CharacterController component is essential."},{"order":3,"type":"subheading","text":"1. Raycasting for Line-of-Sight and Interaction"},{"order":4,"type":"paragraph","text":"Raycasting projects an invisible line into the physics world and returns information about what it intersects. This is commonly used for weapon shooting, ground detection, and line-of-sight calculations."},{"order":5,"type":"code","text":"using UnityEngine;

public class RaycastExample : MonoBehaviour
{
    public Transform firePoint;
    public float maxDistance = 10f;
    public LayerMask hitLayer;

    void Update()
    {
        if (Input.GetButtonDown("Fire1"))
        {
            RaycastHit hit;
            if (Physics.Raycast(firePoint.position, firePoint.forward, out hit, maxDistance, hitLayer))
            {
                Debug.Log("Hit object: " + hit.collider.name + " at distance: " + hit.distance);

                // Apply force if the rigidBody exists
                if (hit.rigidbody != null)
                {
                    hit.rigidbody.AddForce(firePoint.forward * 5f, ForceMode.Impulse);
                }
            }
        }
    }
}"},{"order":6,"type":"subheading","text":"2. Overlap Queries for Area Effects"},{"order":7,"type":"paragraph","text":"Unlike raycasts which check a line, overlap queries check a volume (like a sphere, box, or capsule) for any colliders currently intersecting it. This is ideal for explosive damage, proximity triggers, or gathering nearby items."},{"order":8,"type":"code","text":"using UnityEngine;

public class OverlapQueryExample : MonoBehaviour
{
    public float explosionRadius = 5f;
    public LayerMask damageableLayer;

    void TriggerExplosion()
    {
        Collider[] hitColliders = Physics.OverlapSphere(transform.position, explosionRadius, damageableLayer);

        foreach (Collider hitCollider in hitColliders)
        {
            Debug.Log("Explosion affected: " + hitCollider.name);
            // Apply damage logic here
        }
    }

    void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.red;
        Gizmos.DrawWireSphere(transform.position, explosionRadius);
    }
}"},{"order":9,"type":"subheading","text":"3. Implementing a Robust Character Controller"},{"order":10,"type":"paragraph","text":"Unity provides a built-in CharacterController component that handles collision detection and response against geometry without needing a full Rigidbody. It prevents characters from sliding down slopes or bouncing off walls unrealistically."},{"order":11,"type":"code","text":"using UnityEngine;

[RequireComponent(typeof(CharacterController))]
public class PlayerController : MonoBehaviour
{
    private CharacterController controller;
    private Vector3 playerVelocity;
    private bool groundedPlayer;

    public float playerSpeed = 7.0f;
    public float jumpHeight = 1.5f;
    public float gravityValue = -9.81f;

    void Start()
    {
        controller = GetComponent<CharacterController>();
    }

    void Update()
    {
        groundedPlayer = controller.isGrounded;
        if (groundedPlayer && playerVelocity.y < 0)
        {
            playerVelocity.y = 0f;
        }

        float moveX = Input.GetAxis("Horizontal");
        float moveZ = Input.GetAxis("Vertical");
        Vector3 move = new Vector3(moveX, 0, moveZ);
        controller.Move(move * Time.deltaTime * playerSpeed);

        // Changes the height position of the player relative to changes in y-velocity.
        if (Input.GetButtonDown("Jump") && groundedPlayer)
        {
            playerVelocity.y += Mathf.Sqrt(jumpHeight * -3.0f * gravityValue);
        }

        playerVelocity.y += gravityValue * Time.deltaTime;
        controller.Move(playerVelocity * Time.deltaTime);
    }
}"},{"order":12,"type":"subheading","text":"Best Practices Summary"},{"order":13,"type":"bullet_point","text":"Always use LayerMasks in Raycasts and Overlap queries to avoid unnecessary calculations with irrelevant game objects."},{"order":14,"type":"bullet_point","text":"Use NonAlloc physics methods (like Physics.OverlapSphereNonAlloc) in performance-heavy scenarios to reduce garbage collection overhead."},{"order":15,"type":"bullet_point","text":"Call controller.Move() once per frame within the Update loop to ensure smooth character displacement."}]
